        let client = client.clone(); // cheap handle clone, moved into the async block
        async move {
            match client.get(*u).send().await {
                Ok(resp) => format!("{:<30} {}", u, resp.status().as_u16()),
                Err(e) => format!("{:<30} ERROR {}", u, e), // Result forces both arms to be handled
            }
        }
    });
    for line in join_all(tasks).await {
        println!("{line}");
    }
}
