**Java 21+** with virtual threads, where plain blocking code scales:

```java
import java.net.URI;
import java.net.http.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;

public class Fetch {
    public static void main(String[] args) throws Exception {
        var urls = List.of("https://example.com", "https://openjdk.org", "https://httpbin.org/delay/5");
        var client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();

        try (var exec = Executors.newVirtualThreadPerTaskExecutor()) {   // one cheap virtual thread per task
            List<Future<String>> futures = urls.stream().map(u -> exec.submit(() -> {
                var req = HttpRequest.newBuilder(URI.create(u)).timeout(Duration.ofSeconds(2)).build();
                try {
                    var resp = client.send(req, HttpResponse.BodyHandlers.discarding()); // blocking style, still scales
                    return "%-30s %d".formatted(u, resp.statusCode());
                } catch (Exception e) {
                    return "%-30s ERROR %s".formatted(u, e);
                }
            })).toList();
            for (var f : futures) System.out.println(f.get());
        }
    }
}
```

